tool_calls.arguments:
{"command":"# Get exact spec from current deployment (without status)
kubectl get deploy app -n default --output=yaml 2>&1 | grep -A 100 "spec:" > /tmp/spec_only.yaml && head -50 /tmp/spec_only.yaml

# Now create fixed version with proper volume mount for service account token"}

{"command":"# Check the actual contents of the deployment-simple.yaml file
cat /tmp/deployment-simple.yaml | head -30 && echo "---" && wc -l /tmp/deployment-simple.yaml

# Verify with python or jq to check YAML validity if available, otherwise let's look more closely at structure"}

{"command":"kubectl get deploy app -n default --output=yaml 2>&1 | grep -A 30 "spec:" && echo "---" && kubectl describe pod app-78b89b59b5-lqmg9 -n default 2>&1 | grep -A 20 "Mounts:"

# Check if there's any difference in the service account annotation that might prevent proper mounting
